# Let me try using a simple backtracking approach with some heuristics

def solve_social_golfers():
    n_golfers = 50
    n_groups = 10
    group_size = 5
    n_weeks = 6

    # schedule[w][p] = group of golfer p in week w
    schedule = [[-1] * n_golfers for _ in range(n_weeks)]

    # Track which pairs have been together
    # pair_together[i][j] = True if golfers i and j have been in same group
    pair_together = [[False] * n_golfers for _ in range(n_golfers)]

    def is_valid_assignment(week, golfer, group):
        # Check if assigning golfer to group in week is valid
        # Find other golfers already in this group this week
        for other in range(n_golfers):
            if schedule[week][other] == group and other != golfer:
                # Check if this pair has been together before
                if pair_together[min(golfer, other)][max(golfer, other)]:
                    return False
        return True

    def assign(week, golfer, group):
        schedule[week][golfer] = group
        for other in range(n_golfers):
            if schedule[week][other] == group and other != golfer:
                pair_together[min(golfer, other)][max(golfer, other)] = True

    def unassign(week, golfer, group):
        for other in range(n_golfers):
            if schedule[week][other] == group and other != golfer:
                pair_together[min(golfer, other)][max(golfer, other)] = False
        schedule[week][golfer] = -1

    def backtrack(week, golfer):
        if week == n_weeks:
            return True
        if golfer == n_golfers:
            return backtrack(week + 1, 0)

        # Try each group
        for group in range(n_groups):
            # Check if group is full
            count = sum(1 for p in range(n_golfers) if schedule[week][p] == group)
            if count >= group_size:
                continue

            if is_valid_assignment(week, golfer, group):
                assign(week, golfer, group)
                if backtrack(week, golfer + 1):
                    return True
                unassign(week, golfer, group)

        return False

    # This naive approach will be too slow for 50 golfers
