    def solve_with_z3():
        n_golfers = 50
        n_groups = 10
        group_size = 5
        n_weeks = 6

        # Create variables: x[w][p] = group of golfer p in week w
        x = [[Int(f'x_{w}_{p}') for p in range(n_golfers)] for w in range(n_weeks)]

        solver = Optimize()

        # Domain constraints: each x[w][p] in 0..9
        for w in range(n_weeks):
            for p in range(n_golfers):
                solver.add(x[w][p] >= 0, x[w][p] < n_groups)

        # Each week, each group has exactly 5 golfers
        for w in range(n_weeks):
            for g in range(n_groups):
                solver.add(Sum([If(x[w][p] == g, 1, 0) for p in range(n_golfers)]) == group_size)

        # No pair of golfers in same group more than once
        for p1 in range(n_golfers):
            for p2 in range(p1 + 1, n_golfers):
                # Count how many weeks they're in the same group
                same_group_count = Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(n_weeks)])
                solver.add(same_group_count <= 1)

        print("Solving with Z3...")
        result = solver.check()
        print(f"Result: {result}")

        if result == sat:
            m = solver.model()
            solution = []
            for w in range(n_weeks):
                for p in range(n_golfers):
                    solution.append(m[x[w][p]].as_long())
            return solution
        return None

    sol = solve_with_z3()
