import random
from itertools import combinations

def solve_social_golfers_greedy():
    n_golfers = 50
    n_groups = 10
    group_size = 5
    n_weeks = 6

    random.seed(42)

    for attempt in range(100):
        # Initialize
        schedule = [[-1] * n_golfers for _ in range(n_weeks)]
        pair_used = [[False] * n_golfers for _ in range(n_golfers)]

        success = True

        for week in range(n_weeks):
            # Create groups for this week
            # Use a greedy approach: assign golfers to groups
            # trying to avoid pairs that have been used

            # Shuffle golfers
            golfers = list(range(n_golfers))
            random.shuffle(golfers)

            groups = [[] for _ in range(n_groups)]

            for golfer in golfers:
                # Find best group for this golfer
                best_group = -1
                best_score = -1

                for g in range(n_groups):
                    if len(groups[g]) >= group_size:
                        continue

                    # Score: how many unused pairs with current group members
                    score = 0
                    valid = True
                    for other in groups[g]:
                        if pair_used[min(golfer, other)][max(golfer, other)]:
                            valid = False
                            break
                        score += 1

                    if valid:
                        if score > best_score:
                            best_score = score
                            best_group = g

                if best_group == -1:
                    # Try to find any valid group
                    for g in range(n_groups):
                        if len(groups[g]) >= group_size:
                            continue
                        valid = True
                        for other in groups[g]:
                            if pair_used[min(golfer, other)][max(golfer, other)]:
                                valid = False
                                break
                        if valid:
                            best_group = g
                            break

                if best_group == -1:
                    success = False
                    break

                # Assign golfer to best_group
                groups[best_group].append(golfer)
                for other in groups[best_group][:-1]:
                    pair_used[min(golfer, other)][max(golfer, other)] = True

            if not success:
                break

            # Record schedule
            for g in range(n_groups):
                for golfer in groups[g]:
                    schedule[week][golfer] = g

        if success:
            # Verify solution
            for p1 in range(n_golfers):
                for p2 in range(p1+1, n_golfers):
                    count = 0
                    for w in range(n_weeks):
                        if schedule[w][p1] == schedule[w][p2]:
                            count += 1
                    if count > 1:
                        success = False
                        break
                if not success:
                    break

            if success:
                print(f"Solution found on attempt {attempt}!")
                # Convert to flat list
                flat = []
                for w in range(n_weeks):
                    for p in range(n_golfers):
                        flat.append(schedule[w][p])
                return flat

    print("No solution found with greedy approach")
    return None

sol = solve_social_golfers_greedy()
