import random
from itertools import combinations

def solve_social_golfers_local_search():
    n_golfers = 50
    n_groups = 10
    group_size = 5
    n_weeks = 6

    random.seed(123)

    # Initialize with random valid partitions for each week
    def random_partition():
        golfers = list(range(n_golfers))
        random.shuffle(golfers)
        groups = []
        for i in range(n_groups):
            groups.append(golfers[i*group_size:(i+1)*group_size])
        return groups

    schedule = [random_partition() for _ in range(n_weeks)]

    def count_violations():
        """Count number of pair violations"""
        pair_count = {}
        for w in range(n_weeks):
            for g in range(n_groups):
                for p1 in schedule[w][g]:
                    for p2 in schedule[w][g]:
                        if p1 < p2:
                            key = (p1, p2)
                            pair_count[key] = pair_count.get(key, 0) + 1

        violations = sum(max(0, c - 1) for c in pair_count.values())
        return violations

    def try_swap(week, g1, g2, i1, i2):
        """Try swapping golfer i1 from group g1 with golfer i2 from group g2"""
        old_violations = count_violations()

        # Perform swap
        schedule[week][g1][i1], schedule[week][g2][i2] = schedule[week][g2][i2], schedule[week][g1][i1]

        new_violations = count_violations()

        if new_violations <= old_violations:
            return True  # Accept
        else:
            # Revert
            schedule[week][g1][i1], schedule[week][g2][i2] = schedule[week][g2][i2], schedule[week][g1][i1]
            return False

    # This is too slow - count_violations is O(weeks * groups * group_size^2)
    # Let's use a more efficient approach

    # Use incremental violation counting
    pair_count = {}
    for w in range(n_weeks):
        for g in range(n_groups):
            for p1 in schedule[w][g]:
                for p2 in schedule[w][g]:
                    if p1 < p2:
                        key = (p1, p2)
                        pair_count[key] = pair_count.get(key, 0) + 1

    def get_violations():
        return sum(max(0, c - 1) for c in pair_count.values())

    def update_pair(p1, p2, delta):
        key = (min(p1,p2), max(p1,p2))
        pair_count[key] = pair_count.get(key, 0) + delta

    def swap_and_update(week, g1, g2, i1, i2):
        """Swap golfers and update pair counts"""
        a = schedule[week][g1][i1]
        b = schedule[week][g2][i2]

        # Remove old pairs
        for other in schedule[week][g1]:
            if other != a:
                update_pair(a, other, -1)
        for other in schedule[week][g2]:
            if other != b:
                update_pair(b, other, -1)

        # Perform swap
        schedule[week][g1][i1] = b
        schedule[week][g2][i2] = a

        # Add new pairs
        for other in schedule[week][g1]:
            if other != b:
                update_pair(b, other, 1)
        for other in schedule[week][g2]:
            if other != a:
                update_pair(a, other, 1)

    best_violations = get_violations()
    print(f"Initial violations: {best_violations}")

    # Simulated annealing
    temperature = 100.0
    cooling_rate = 0.995

    for iteration in range(1000000):
        if best_violations == 0:
            print(f"Solution found at iteration {iteration}!")
            break

        # Random move: swap two golfers in the same week
        week = random.randint(0, n_weeks - 1)
        g1 = random.randint(0, n_groups - 1)
        g2 = random.randint(0, n_groups - 1)
        while g2 == g1:
            g2 = random.randint(0, n_groups - 1)
        i1 = random.randint(0, group_size - 1)
        i2 = random.randint(0, group_size - 1)

        old_violations = get_violations()
        swap_and_update(week, g1, g2, i1, i2)
        new_violations = get_violations()

        delta = new_violations - old_violations

        if delta <= 0 or random.random() < (0.01 ** (delta / max(temperature, 0.001))):
            # Accept move
            if new_violations < best_violations:
                best_violations = new_violations
                if iteration % 10000 == 0:
                    print(f"Iteration {iteration}: violations = {best_violations}")
        else:
            # Revert
            swap_and_update(week, g1, g2, i1, i2)

        temperature *= cooling_rate

    if best_violations == 0:
        # Convert to flat list
        flat = []
        for w in range(n_weeks):
            for g in range(n_groups):
                for p in schedule[w][g]:
                    pass  # We need to track which group each golfer is in

        # Rebuild flat solution
        solution = [0] * (n_weeks * n_golfers)
        for w in range(n_weeks):
            for g in range(n_groups):
                for p in schedule[w][g]:
                    solution[w * n_golfers + p] = g
        return solution

    print(f"Best violations after search: {best_violations}")
    return None

